SELECT
  count(*) totcnt
FROM
  ttokssaemdb.memo memo,
  ttokssaemdb.branch branch,
  ttokssaemdb.member member

  AND memo.branchid = branch.branchid
  AND memo.memberid = member.memberid

    AND memo.branchid = #{session_branchid}


    AND (
      memo.memo LIKE #{likeQuery}
      OR member.membername LIKE #{likeQuery}
    )

SELECT R1.* FROM( SELECT branch.branchid, branch.branchname, member.memberid, member.membername, memo.memoid, memo.memo, DATE_FORMAT(memo.startdate, '%Y-%m-%d') startdate, DATE_FORMAT(memo.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttokssaemdb.memo memo, ttokssaemdb.branch branch, ttokssaemdb.member member
AND memo.branchid = branch.branchid AND memo.memberid = member.memberid
AND memo.branchid = #{session_branchid}
AND ( memo.memo LIKE #{likeQuery} OR member.membername LIKE #{likeQuery} )
memo.memoid memo.regdate DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}

